SELECT 100.0 * SUM(CAST(energy_kwh AS FLOAT)) / SUM(CAST(energy_kwh AS FLOAT)) OVER () AS total_energy_pct
FROM gishub.fleet.charging_sessions
WHERE location_type = 'public_dc';

SELECT
  100.0 * SUM(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END) / SUM(energy_kwh) AS pct_public_dc_energy
FROM gishub.fleet.charging_sessions;
